import {TYPES,seed,canPlace,findSpace,validIP,validateData} from './model.js';
const icons={map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Z"/><path d="M9 3v16M15 5v16"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',network:'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="7" height="5" rx="1"/><rect x="15" y="16" width="7" height="5" rx="1"/><path d="M12 8v4H5v4m7-4h7v4"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',fit:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v2M12 17h.01"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>',check:'<path d="m5 12 4 4L19 6"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',link:'<path d="m10 13 4-4m-6 2-3 3a4 4 0 0 0 6 6l3-3m-4-10 3-3a4 4 0 0 1 6 6l-3 3"/>',layers:'<path d="m3 7 9-5 9 5-9 5Zm0 5 9 5 9-5M3 17l9 5 9-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',undo:'<path d="M4 10h9a7 7 0 0 1 0 14M4 10l5-5m-5 5 5 5"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.chip}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=seed(),storageProblem=false;try{const s=localStorage.getItem('floorlink-v1');if(s)data=validateData(JSON.parse(s));}catch{storageProblem=true;}
let panelId=null,deviceId=null,editing=false,formOpen=false,directoryOpen=innerWidth>700,showLinks=true,query='',zoom=1,pan={x:0,y:0},history=[],drag=null,openTimer=null;const expanded=new Set();let lastRenderedPanel=null;
const app=document.querySelector('#app');
function save(){try{localStorage.setItem('floorlink-v1',JSON.stringify(data));storageProblem=false;}catch{storageProblem=true;toast('Browser storage is unavailable. Export your layout to keep your changes.');}updateSaveLabel();}
function snapshot(){history.push(JSON.stringify(data));if(history.length>30)history.shift();}
function updateSaveLabel(){const e=document.querySelector('#save-label');if(e)e.textContent=storageProblem?'Export to keep your changes':'Layout saved in this browser';}
let toastTimer;function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3300);}
function panelStatus(id){const ds=data.devices.filter(d=>d.panelId===id);return ds.some(d=>d.status==='attention')?'attention':ds.length&&ds.every(d=>d.status==='offline')?'offline':'online';}
function panelLinks(){const pairs=new Map();for(const d of data.devices)for(const id of d.connections){const to=data.devices.find(x=>x.id===id);if(!to||to.panelId===d.panelId)continue;const key=[d.panelId,to.panelId].sort().join('|');const a=data.panels.find(p=>p.id===d.panelId),b=data.panels.find(p=>p.id===to.panelId);pairs.set(key,[a.x,a.y,b.x,b.y]);}return [...pairs.values()];}
function deviceCount(p){return data.devices.filter(d=>d.panelId===p).length;}
function shell(){app.innerHTML=`<header><a class="brand" href="index.html" aria-label="Floorlink home" style="text-decoration:none;color:inherit"><span class="brand-mark">${icon('layers')}</span>floorlink<span style="color:#b5c4bb;font-size:25px">.</span></a><div class="divider"></div><div class="plant">${icon('grid')}<div><span>WORKSPACE</span>North Plant <span style="display:inline;margin-left:9px;font-size:12px">⌄</span></div></div><div class="header-right"><span class="demo">INTERACTIVE DEMO</span><button class="btn" data-action="help">${icon('help')}Quick guide</button><span class="avatar" aria-label="Demo workspace">NP</span></div></header><div class="app-shell"><nav class="nav-rail" aria-label="Workspace views"><button class="active" data-action="home" title="Factory floor" aria-label="Factory floor">${icon('map')}</button><button data-action="directory" title="IP directory" aria-label="IP directory">${icon('network')}</button><button data-action="panel-list" title="Browse panels" aria-label="Browse panels">${icon('grid')}</button><button class="bottom" data-action="help" title="Quick guide" aria-label="Quick guide">${icon('help')}</button></nav><main class="workspace ${directoryOpen?'':'directory-hidden'}"><div class="workspace-head"><div><div class="eyebrow">NETWORK ATLAS / NORTH PLANT</div><h1>Your floor. Every connection.</h1><p class="subtitle">Explore panels, find devices, and bring your network into focus.</p></div><div class="workspace-actions"><button class="btn" data-action="import" title="Import layout JSON">${icon('upload')}<span class="export-label">Import</span></button><button class="btn" data-action="export">${icon('download')}<span class="export-label">Export layout</span></button><button class="btn primary" data-action="directory" aria-expanded="${directoryOpen}">${icon('network')}IP directory ${icon('down')}</button></div></div><div class="content"><div class="map-column"><section class="map-card" aria-label="Interactive factory floor plan"><div class="map-top"><div class="floor-label">${icon('layers')}Ground floor <span> / 01</span></div><button class="btn ${showLinks?'active':''}" data-action="links" aria-pressed="${showLinks}">${icon('link')}Connections</button></div>${floor()}<div class="map-legend"><span><i class="dot"></i>Connected</span><span><i class="dot attention"></i>Needs attention</span><span>Sample network · click a panel to explore</span></div><div class="map-controls"><button data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><button data-action="fit" id="zoom-value" title="Reset map view">100%</button><button data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button data-action="fit" aria-label="Fit floor plan">${icon('fit')}</button></div><div id="cabinet-mount"></div></section><div class="panel-strip" aria-label="Factory panels">${data.panels.map(p=>`<button class="panel-tile" data-panel="${esc(p.id)}"><div class="tile-top"><i class="dot ${panelStatus(p.id)}"></i>${esc(p.name)}</div><div class="tile-desc">${esc(p.title)}</div><div class="tile-count">${deviceCount(p.id)} devices ${data.devices.filter(d=>d.panelId===p.id&&d.status==='attention').length?'· '+data.devices.filter(d=>d.panelId===p.id&&d.status==='attention').length+' alert':''}</div></button>`).join('')}</div></div><aside class="side" id="side" aria-label="IP directory"></aside></div><footer class="footer"><span><i class="dot"></i><b id="total-count">${data.devices.length}</b> devices across 6 panels <span style="margin:0 7px;color:#c0c9bd">|</span> Demonstration data</span><span>${icon('check')}<span id="save-label">Layout saved in this browser</span></span></footer></main></div><input type="file" id="import-file" accept=".json,application/json" hidden>`;renderSide();renderCabinet();wireMap();updateMap();updateSaveLabel();}
function machine(x,y,w,h,type='station'){return `<g transform="translate(${x} ${y})"><rect width="${w}" height="${h}" rx="3" fill="#e1e6dc" stroke="#c2cbbd"/><rect x="5" y="5" width="${w-10}" height="${h-10}" rx="2" fill="#edf0e7" stroke="#cbd3c5"/>${type==='tank'?`<circle cx="${w/2}" cy="${h/2}" r="${Math.min(w,h)/2-10}" fill="#dce4d4" stroke="#b7c5ae"/><circle cx="${w/2}" cy="${h/2}" r="8" fill="#c5d2bc"/>`:`<rect x="10" y="10" width="${w*.3}" height="${h-20}" rx="2" fill="#d6dece"/><path d="M${w-13} 11v${h-22}" stroke="#c7d0bf" stroke-width="3"/>`}</g>`;}
function conveyor(x,y,w,h){return `<g><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="url(#belt)" stroke="#becab7"/><path d="M${x} ${y-3}h${w}m-${w} ${h+6}h${w}" stroke="#aebaab" stroke-width="2"/><path d="m${x+w/2-10} ${y+h/2}h20m-5-4 5 4-5 4" stroke="#95a98a" fill="none"/></g>`;}
function floor(){return `<svg class="floor-svg" viewBox="0 0 1100 700" aria-label="Factory floor with six interactive panels"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#dee5d9"/></pattern><pattern id="belt" width="7" height="7" patternUnits="userSpaceOnUse"><rect width="7" height="7" fill="#e0e7d8"/><path d="M1 0v7" stroke="#c1cdba"/></pattern><pattern id="hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0v6" stroke="#e0e5d8" stroke-width="2"/></pattern><filter id="shadow" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dx="0" dy="3" stdDeviation="4" flood-color="#304b2b" flood-opacity=".1"/></filter></defs><rect width="1100" height="700" fill="url(#dots)"/><g class="map-scene"><rect x="81" y="104" width="950" height="492" fill="#f5f6ef" stroke="#a4b29b" stroke-width="5"/><rect x="95" y="118" width="922" height="464" fill="none" stroke="#d4dccb"/><path d="M294 106v206m0 54v228M810 106v213m0 48v226M82 337h136m58 0h299m55 0h400" stroke="#aab8a0" stroke-width="4"/><path d="M85 348h942M304 110v472M799 110v472" stroke="#d8dfcb" stroke-dasharray="5 5"/><rect x="316" y="319" width="470" height="40" fill="url(#hatch)"/><text x="552" y="343" text-anchor="middle" fill="#9ba98d" font-size="8" letter-spacing="3">PEDESTRIAN WALKWAY</text><text x="113" y="139" class="room-number">01 / INFRASTRUCTURE</text><text x="113" y="285" class="room-label">NETWORK ROOM</text><text x="333" y="139" class="room-number">02 / PRODUCTION</text><text x="536" y="290" class="room-label">ASSEMBLY</text><text x="831" y="139" class="room-number">03 / LOGISTICS</text><text x="844" y="285" class="room-label">RECEIVING</text><text x="110" y="379" class="room-number">04 / SERVICES</text><text x="121" y="565" class="room-label">UTILITIES</text><text x="329" y="379" class="room-number">05 / END OF LINE</text><text x="502" y="565" class="room-label">PACKAGING</text><text x="831" y="379" class="room-number">06 / STORAGE</text><text x="847" y="565" class="room-label">WAREHOUSE</text>${machine(115,207,48,40)}${machine(176,207,48,40)}${machine(237,155,27,94)}${conveyor(335,193,190,27)}${conveyor(594,193,188,27)}${[340,410,480,599,669,739].map(x=>machine(x,151,37,30)).join('')}${[340,410,480,599,669,739].map(x=>machine(x,233,37,33)).join('')}${machine(844,168,62,66)}${machine(933,168,60,66)}${machine(116,401,62,62,'tank')}${machine(202,401,62,62,'tank')}${machine(115,512,48,24)}${machine(213,512,48,24)}${conveyor(340,430,248,25)}${machine(343,480,73,52)}${machine(646,405,111,76)}${machine(645,505,53,31)}${machine(710,505,46,31)}${[841,900,959].map(x=>[404,432,500,528].map(y=>machine(x,y,37,20)).join('')).join('')}<g id="network-lines" style="display:${showLinks?'':'none'}">${panelLinks().map(([x,y,a,b])=>`<path class="network-line" d="M${x} ${y}V337H${a}V${b}"/>`).join('')}</g>${data.panels.map(p=>`<g class="panel-marker ${panelStatus(p.id)==='attention'?'warning':''}" data-panel="${esc(p.id)}" role="button" tabindex="0" aria-label="Open ${esc(p.name)} ${esc(p.title)}, ${deviceCount(p.id)} devices" transform="translate(${p.x-55} ${p.y-23})"><rect class="marker-body" width="110" height="46" rx="6"/><rect x="9" y="11" width="19" height="24" rx="2" fill="#e5eee1" stroke="#9db995"/><path d="M13 17h11m-11 5h11m-11 5h11" stroke="#8ba680"/><circle class="marker-dot" cx="99" cy="10" r="2.5"/><text x="36" y="20" class="marker-title">${esc(p.name)}</text><text x="36" y="33" class="marker-subtitle">${deviceCount(p.id)} devices</text></g>`).join('')}<path d="M445 596h110" stroke="#fbfcfa" stroke-width="7"/><path d="M445 596v-27m110 27v-27" stroke="#a4b29b" stroke-width="2"/><text x="500" y="621" text-anchor="middle" font-size="9" fill="#a3af98" letter-spacing="2">MAIN ENTRANCE</text><g transform="translate(993 637)"><path d="M0 16V-12m-5 7 5-7 5 7" stroke="#8da081" fill="none"/><text x="0" y="-19" text-anchor="middle" font-size="9" fill="#8da081">N</text></g><path d="M100 634v5h90v-5m-45 0v5" stroke="#a3b096" fill="none"/><text x="144" y="653" text-anchor="middle" fill="#a3b096" font-size="8">0 ───── 10 m · schematic</text></g></svg>`;}
function renderSide(){const el=document.querySelector('#side');if(!el)return;if(deviceId&&data.devices.some(d=>d.id===deviceId)){renderInspector(el);return;}el.className='side';el.setAttribute('aria-label','IP directory');el.innerHTML=`<div class="side-top"><div class="side-title"><span>${icon('network')}IP directory</span><button class="btn icon" data-action="directory" aria-label="Close IP directory" style="border:0;padding:2px">${icon('close')}</button></div><div class="small">Every address. One place.</div><div class="search">${icon('search')}<input id="ip-search" type="search" placeholder="Search IP, device, or panel…" aria-label="Search IP, device, or panel" value="${esc(query)}"></div><div class="summary-stats"><div><b>${data.devices.length}</b><span>DEVICES</span></div><div><b>${new Set(data.devices.map(d=>d.ip.split('.').slice(0,3).join('.'))).size}</b><span>SUBNETS</span></div><div><b>6</b><span>PANELS</span></div></div></div><div class="subnets" id="subnets"></div><div class="side-footer">${icon('search')}Select an address to locate its device</div>`;renderSubnets();}
function renderSubnets(){const e=document.querySelector('#subnets');if(!e)return;const groups=new Map();for(let i=0;i<5;i++)groups.set(`172.168.${i}`,[]);for(const d of data.devices){const p=data.panels.find(p=>p.id===d.panelId);if(query&&!`${d.ip} ${d.name} ${p.name} ${p.title}`.toLowerCase().includes(query.toLowerCase()))continue;const prefix=d.ip.split('.').slice(0,3).join('.');if(!groups.has(prefix))groups.set(prefix,[]);groups.get(prefix).push(d);}let any=false;e.innerHTML=[...groups].sort(([a],[b])=>a.localeCompare(b,undefined,{numeric:true})).map(([prefix,devices])=>{if(query&&!devices.length)return '';any ||=devices.length>0;const open=query||expanded.has(prefix);return `<div class="subnet"><button class="subnet-toggle ${open?'open':''}" data-subnet="${esc(prefix)}" aria-expanded="${!!open}">${icon('chevron')}${esc(prefix)}.xxx <span class="count-pill">${devices.length} used</span></button>${open?devices.sort((a,b)=>a.ip.localeCompare(b.ip,undefined,{numeric:true})).map(d=>`<button class="ip-row" data-device="${esc(d.id)}"><i class="dot ${esc(d.status)}"></i><span><span class="ip">${esc(d.ip)}</span><span class="ip-name" style="display:block">${esc(d.name)} · ${esc(data.panels.find(p=>p.id===d.panelId).name)}</span></span>${icon('arrow')}</button>`).join(''):''}</div>`;}).join('');if(query&&!any)e.innerHTML='<div class="empty">No matching devices.<br>Try an IP address, panel, or device name.</div>';}
function hardware(d){const t=TYPES[d.type];return `<button class="device ${d.type} ${deviceId===d.id?'selected':''}" style="grid-column:${d.slot+1} / span ${t.width};grid-row:1" data-device="${esc(d.id)}" data-hardware="${esc(d.id)}" ${editing?'draggable="true"':''} aria-label="${esc(d.name)}, ${esc(d.ip)}${editing?', drag to reposition':''}" title="${esc(d.name)} · ${esc(d.ip)}"><span class="device-top"><span>${t.short}</span><span style="font-size:5px">${d.status==='attention'?'ALM':'RUN'}</span></span><span class="device-leds"><i style="${d.status==='attention'?'background:#d6a446':''}"></i><i></i><i></i></span>${d.type==='switch'?`<span class="ports">${'<i></i>'.repeat(12)}</span>`:d.type==='plc'||d.type==='io'?'<span class="module-slots"></span>':d.type==='vfd'?'<span class="vfd-screen">60.0</span><span class="vfd-keys"><i></i><i></i><i style="background:#b46454"></i></span>':d.type==='hmi'?'<span class="screen">SYSTEM OK</span>':'<span class="antenna"></span>'}<span class="device-label">${esc(d.name)}</span><span class="device-ip">${esc(d.ip)}</span></button>`;}
function renderCabinet(){const mount=document.querySelector('#cabinet-mount');if(!panelId){mount.innerHTML='';lastRenderedPanel=null;return;}const p=data.panels.find(p=>p.id===panelId);const animate=lastRenderedPanel!==panelId;lastRenderedPanel=panelId;mount.innerHTML=`<section style="animation:${animate?'':'none'}" class="cabinet-layer ${editing?'editing':''}" aria-label="${esc(p.name)} cabinet front view"><div class="cabinet-heading"><div><h2><button class="btn icon" style="padding:4px;border:0" data-action="close-panel" aria-label="Back to factory floor">${icon('back')}</button>${esc(p.name)} <span style="font-weight:400;color:#92a188"> / ${esc(p.title)}</span></h2><div class="small" style="padding-left:32px">${esc(p.area)} · ${deviceCount(p.id)} devices · Front elevation</div></div><div class="cabinet-heading-actions">${editing?`<button class="btn icon" data-action="undo" aria-label="Undo layout edit" ${history.length?'':'disabled'}>${icon('undo')}</button>`:''}<button class="btn ${editing?'primary':''}" data-action="edit-panel">${icon(editing?'check':'edit')}${editing?'Done':'Edit panel'}</button></div></div><div class="cabinet-workspace">${editing?`<div class="palette"><h3>Device library</h3><p>Drag onto a rail, or click to add. Equipment snaps to open slots.</p>${Object.entries(TYPES).map(([type,t])=>`<button class="palette-item" draggable="true" data-add="${type}" aria-label="Add ${t.name}" title="Drag or click to add ${t.name}"><span class="type-icon">${t.short}</span><span>${t.name}<span style="display:block;color:#9ca68e;font-size:8px;margin-top:3px">${t.width} slots</span></span></button>`).join('')}</div>`:''}<div class="cabinet"><div class="cabinet-label"><b>${esc(p.name)} / 480V</b><span>INCOMING POWER ↓</span></div>${[0,1,2].map(row=>`<div class="din-row" data-row="${row}" aria-label="DIN rail ${row+1}"><span class="rail-number">R${row+1}</span>${data.devices.filter(d=>d.panelId===panelId&&d.row===row).map(hardware).join('')}</div>`).join('')}<div class="terminal-strip"></div><div class="cabinet-ground"><span>PE / GROUND</span><div class="ground-bar"></div><span>IP54 · SCHEMATIC</span></div></div></div><div class="cabinet-bottom">${icon(editing?'grid':'chip')}${editing?'Snapping enabled · 12 slots per rail · Changes save automatically':'Select a device to inspect its address and connections'}</div></section>`;wireDrag();}
function connected(d){return data.devices.filter(x=>d.connections.includes(x.id)||x.connections.includes(d.id));}
function renderInspector(el){const d=data.devices.find(d=>d.id===deviceId),p=data.panels.find(p=>p.id===d.panelId),links=connected(d);el.className='side inspector';el.setAttribute('aria-label','Device details');el.innerHTML=`<div class="side-top"><div class="side-title"><span>${icon('chip')}Device details</span><button class="btn icon" style="padding:2px;border:0" data-action="back-directory" aria-label="Back to IP directory">${icon('close')}</button></div><div class="small">${esc(p.name)} <span style="padding:0 5px">/</span> Rail ${d.row+1} · Slot ${d.slot+1}</div></div><div class="inspector-scroll"><div class="device-hero">${icon(d.type==='switch'?'network':'chip')}<div><div class="eyebrow">${TYPES[d.type].name}</div><strong>${esc(d.model)}</strong></div></div><h3>${esc(d.name)}</h3><div class="ip-badge">${esc(d.ip)}<button data-action="copy-ip" aria-label="Copy IP address" title="Copy IP address">${icon('copy')}</button></div>${formOpen?deviceForm(d):`<p class="description">${esc(d.description)}</p><dl class="meta-grid"><div><dt>STATUS (SIMULATED)</dt><dd><i class="dot ${esc(d.status)}"></i>${d.status==='attention'?'Needs attention':d.status==='offline'?'Offline':'Connected'}</dd></div><div><dt>LOCATION</dt><dd>${esc(p.area)}</dd></div><div><dt>SUBNET</dt><dd style="font-family:var(--mono);font-size:9px">${esc(d.ip.split('.').slice(0,3).join('.'))}.0/24</dd></div><div><dt>MOUNTING</dt><dd>DIN rail ${d.row+1}</dd></div></dl><div class="section-title">CONNECTIONS <span class="count-pill">${links.length}</span></div>${links.map(x=>`<button class="connection" data-device="${esc(x.id)}">${icon('link')}<span><strong>${esc(x.name)}</strong><small>${esc(x.ip)}</small></span>${icon('arrow')}</button>`).join('')||'<p class="small">No connections assigned. Edit this device to add a link.</p>'}<button class="btn" style="width:100%;margin-top:16px" data-action="edit-device">${icon('edit')}Edit device</button>${editing?`<div style="display:flex;gap:5px;margin-top:9px"><button class="btn" style="flex:1" data-action="move-device" title="Move device to the next rail with available space">${icon('layers')}Move rail</button><button class="btn danger icon" data-action="delete-device" aria-label="Remove device">${icon('trash')}</button></div>`:''}`}</div><div class="side-footer"><i class="dot"></i>Sample device · No live network connection</div>`;}
function deviceForm(d){const links=connected(d).map(x=>x.id);return `<form id="device-form" class="edit-form"><label>Device name<input name="name" value="${esc(d.name)}" required maxlength="60"></label><label>IP address<input name="ip" value="${esc(d.ip)}" required inputmode="decimal" placeholder="172.168.1.20"></label><label>Model<input name="model" value="${esc(d.model)}" required maxlength="80"></label><label>Description<textarea name="description" maxlength="500">${esc(d.description)}</textarea></label><label>Simulated status<select name="status"><option value="online" ${d.status==='online'?'selected':''}>Connected</option><option value="attention" ${d.status==='attention'?'selected':''}>Needs attention</option><option value="offline" ${d.status==='offline'?'selected':''}>Offline</option></select></label><div><div class="section-title">DEVICE CONNECTIONS</div><div class="connection-checks">${data.devices.filter(x=>x.id!==d.id).map(x=>`<label><input type="checkbox" name="connections" value="${esc(x.id)}" ${links.includes(x.id)?'checked':''}>${esc(x.ip)} · ${esc(x.name)}</label>`).join('')}</div></div><p id="form-error" class="form-error" role="alert"></p><div class="form-actions"><button class="btn primary" type="submit">${icon('check')}Save device</button><button class="btn" type="button" data-action="cancel-edit">Cancel</button></div></form>`;}
function setDirectory(open){directoryOpen=open;document.querySelector('.workspace').classList.toggle('directory-hidden',!open);document.querySelector('[aria-expanded][data-action="directory"]')?.setAttribute('aria-expanded',open);}
function openPanel(id,selected=null){clearTimeout(openTimer);const p=data.panels.find(p=>p.id===id);if(!p)return;const changed=panelId!==id;deviceId=selected;formOpen=false;if(changed){editing=false;panelId=null;document.querySelector('#cabinet-mount').innerHTML='';zoom=1.4;pan={x:(550-p.x)*1.1,y:(350-p.y)*1.1};updateMap();openTimer=setTimeout(()=>{panelId=id;renderCabinet();},280);}else renderCabinet();if(selected)setDirectory(true);renderSide();}
function closePanel(){clearTimeout(openTimer);panelId=null;deviceId=null;editing=false;formOpen=false;zoom=1;pan={x:0,y:0};renderCabinet();renderSide();updateMap();}
function refresh(){const q=query;shell();query=q;}
function updateMap(){const e=document.querySelector('.map-scene');if(e)e.style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;const z=document.querySelector('#zoom-value');if(z)z.textContent=`${Math.round(zoom*100)}%`;}
function wireMap(){const svg=document.querySelector('.floor-svg');let pointer=null;svg.addEventListener('pointerdown',e=>{if(e.target.closest('[data-panel]'))return;pointer={x:e.clientX,y:e.clientY,pan:{...pan}};svg.setPointerCapture(e.pointerId);document.querySelector('.map-scene').classList.add('panning');});svg.addEventListener('pointermove',e=>{if(!pointer)return;const scale=1100/svg.getBoundingClientRect().width;pan={x:pointer.pan.x+(e.clientX-pointer.x)*scale,y:pointer.pan.y+(e.clientY-pointer.y)*scale};updateMap();});const finish=()=>{pointer=null;document.querySelector('.map-scene').classList.remove('panning');};svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',finish);svg.addEventListener('wheel',e=>{if(panelId)return;e.preventDefault();zoom=Math.max(.65,Math.min(2.5,zoom+(e.deltaY>0?-.1:.1)));updateMap();},{passive:false});}
function nextIP(){const p=data.panels.find(p=>p.id===panelId);for(let n=30;n<255;n++){const ip=`172.168.${p.subnet??0}.${n}`;if(!data.devices.some(d=>d.ip===ip))return ip;}return null;}
function addDevice(type,position){const place=position||findSpace(data.devices,panelId,type);if(!place){toast('This panel is full. Move or remove a device to make room.');return;}const ip=nextIP();if(!ip){toast('No unused example IP remains in this subnet.');return;}snapshot();const d={id:crypto.randomUUID(),panelId,type,name:`New ${TYPES[type].name.toLowerCase()}`,model:TYPES[type].model,ip,description:'Add a description for this device and connect it to the network.',status:'online',...place,connections:[]};data.devices.push(d);deviceId=d.id;formOpen=true;setDirectory(true);save();refresh();toast('Device added and snapped to rail. Edit its details on the right.');}
function wireDrag(){document.querySelectorAll('[draggable="true"]').forEach(el=>{el.addEventListener('dragstart',e=>{drag=el.dataset.add?{type:el.dataset.add}:{id:el.dataset.hardware,type:data.devices.find(d=>d.id===el.dataset.hardware).type};e.dataTransfer.setData('text/plain',JSON.stringify(drag));e.dataTransfer.effectAllowed=drag.id?'move':'copy';});el.addEventListener('dragend',()=>{drag=null;document.querySelectorAll('.drag-over').forEach(r=>r.classList.remove('drag-over'));});});document.querySelectorAll('.din-row').forEach(row=>{row.addEventListener('dragover',e=>{if(!editing||!drag)return;e.preventDefault();row.classList.add('drag-over');e.dataTransfer.dropEffect=drag.id?'move':'copy';});row.addEventListener('dragleave',e=>{if(!row.contains(e.relatedTarget))row.classList.remove('drag-over');});row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('drag-over');if(!editing||!drag)return;const rect=row.getBoundingClientRect(),r=+row.dataset.row,w=TYPES[drag.type].width,target=Math.max(0,Math.min(12-w,Math.floor((e.clientX-rect.left)/rect.width*12)-Math.floor(w/2)));let choices=Array.from({length:13-w},(_,i)=>i).sort((a,b)=>Math.abs(a-target)-Math.abs(b-target));const slot=choices.find(s=>canPlace(data.devices,panelId,drag.type,r,s,drag.id));if(slot===undefined){toast('No room on that rail. Try another row.');drag=null;return;}if(drag.id){snapshot();const d=data.devices.find(d=>d.id===drag.id);d.row=r;d.slot=slot;save();refresh();toast(`Snapped to rail ${r+1}, slot ${slot+1}.`);}else addDevice(drag.type,{row:r,slot});drag=null;});});}
function exportData(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='floorlink-layout.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('Layout exported, including devices and connections.');}
function help(){const el=document.createElement('div');el.className='modal-shade';el.innerHTML=`<section class="help-modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="eyebrow">WELCOME TO FLOORLINK</div><h2 id="help-title">From the floor to the port.</h2><p>A working prototype of your factory’s network, inspired by real industrial control cabinets.</p><ol><li>Click a panel on the map to open its front view.</li><li>Select any device to see its IP, description, and links.</li><li>Search the IP directory to jump straight to a device.</li><li>Choose <b>Edit panel</b> to drag equipment onto snapping rails.</li><li>Click library items to add them without dragging.</li><li>Edit names, addresses, and connections in Device details.</li></ol><p>Changes save in this browser. Export a JSON backup to transfer your layout. Statuses, wiring, and addresses are example data; this prototype does not scan or control equipment.</p><button class="btn primary" data-action="close-help">Explore the floor ${icon('arrow')}</button></section>`;document.body.append(el);el.querySelector('button').focus();el.addEventListener('click',e=>{if(e.target===el)el.remove();});}
app.addEventListener('click',async e=>{const panel=e.target.closest('[data-panel]');if(panel){openPanel(panel.dataset.panel);return;}const device=e.target.closest('[data-device]');if(device){const d=data.devices.find(d=>d.id===device.dataset.device);openPanel(d.panelId,d.id);return;}const subnet=e.target.closest('[data-subnet]');if(subnet){const key=subnet.dataset.subnet;expanded.has(key)?expanded.delete(key):expanded.add(key);renderSubnets();return;}const add=e.target.closest('[data-add]');if(add){addDevice(add.dataset.add);return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;switch(action){case 'directory':if(deviceId){deviceId=null;formOpen=false;renderSide();renderCabinet();setDirectory(true);}else setDirectory(!directoryOpen);break;case 'home':case 'close-panel':closePanel();break;case 'links':showLinks=!showLinks;document.querySelector('#network-lines').style.display=showLinks?'':'none';e.target.closest('button').classList.toggle('active',showLinks);e.target.closest('button').setAttribute('aria-pressed',showLinks);break;case 'zoom-in':zoom=Math.min(2.5,zoom+.2);updateMap();break;case 'zoom-out':zoom=Math.max(.65,zoom-.2);updateMap();break;case 'fit':zoom=1;pan={x:0,y:0};updateMap();break;case 'edit-panel':editing=!editing;if(!editing)formOpen=false;renderCabinet();renderSide();break;case 'back-directory':deviceId=null;formOpen=false;renderSide();renderCabinet();if(innerWidth<=700)setDirectory(false);break;case 'edit-device':formOpen=true;renderSide();document.querySelector('[name="name"]').focus();break;case 'cancel-edit':formOpen=false;renderSide();break;case 'copy-ip':try{await navigator.clipboard.writeText(data.devices.find(d=>d.id===deviceId).ip);toast('IP address copied.');}catch{toast('Copy unavailable in this browser. Select the displayed address to copy.');}break;case 'move-device':{const d=data.devices.find(d=>d.id===deviceId);let space;for(let i=1;i<3;i++){space=findSpace(data.devices,panelId,d.type,(d.row+i)%3);if(space)break;}if(!space){toast('No free space on another rail.');break;}snapshot();Object.assign(d,space);save();refresh();toast(`Moved to rail ${d.row+1}.`);break;}case 'delete-device':snapshot();data.devices=data.devices.filter(d=>d.id!==deviceId);data.devices.forEach(d=>d.connections=d.connections.filter(id=>id!==deviceId));deviceId=null;formOpen=false;save();refresh();toast('Device removed. Use Undo to restore it.');break;case 'undo':if(history.length){data=JSON.parse(history.pop());if(!data.devices.some(d=>d.id===deviceId))deviceId=null;formOpen=false;save();refresh();toast('Last edit undone.');}break;case 'export':exportData();break;case 'import':document.querySelector('#import-file').click();break;case 'help':help();break;case 'panel-list':closePanel();document.querySelector('.panel-tile').focus();toast('Choose one of the six panels below the map.');break;}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="close-help"]')){document.querySelector('.modal-shade')?.remove();document.querySelector('[data-action="help"]')?.focus();}});
app.addEventListener('input',e=>{if(e.target.id==='ip-search'){query=e.target.value;renderSubnets();}});
app.addEventListener('submit',e=>{if(e.target.id!=='device-form')return;e.preventDefault();const fd=new FormData(e.target),d=data.devices.find(d=>d.id===deviceId),ip=fd.get('ip').trim(),name=fd.get('name').trim(),model=fd.get('model').trim(),err=document.querySelector('#form-error');if(!name||!model){err.textContent='A device name and model are required.';return;}if(!validIP(ip)){err.textContent='Enter a valid IPv4 address, such as 172.168.1.25.';return;}if(data.devices.some(x=>x.id!==d.id&&x.ip===ip)){err.textContent='This IP address is already assigned to another device.';return;}snapshot();const selected=fd.getAll('connections');data.devices.forEach(x=>{x.connections=x.connections.filter(id=>id!==d.id);});Object.assign(d,{name,model,ip,description:fd.get('description').trim(),status:fd.get('status'),connections:selected});formOpen=false;save();refresh();toast('Device details and connections saved.');});
app.addEventListener('change',async e=>{if(e.target.id!=='import-file'||!e.target.files[0])return;const file=e.target.files[0];try{if(file.size>1024*1024)throw Error('Choose a layout smaller than 1 MB.');const imported=validateData(JSON.parse(await file.text()));snapshot();data=imported;panelId=null;deviceId=null;editing=false;formOpen=false;query='';save();refresh();toast('Layout imported. Your previous layout is available with Undo.');}catch(err){toast(`Import failed: ${err.message}`);}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('.modal-shade')){document.querySelector('.modal-shade').remove();return;}if(formOpen){formOpen=false;renderSide();}else if(deviceId){deviceId=null;renderSide();renderCabinet();}else closePanel();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.panel-marker')){e.preventDefault();openPanel(e.target.dataset.panel);}if(document.querySelector('.modal-shade')&&e.key==='Tab'){e.preventDefault();document.querySelector('.modal-shade button').focus();}});
shell();if(storageProblem)toast('Saved layout could not be loaded. Showing the example floor.');
